--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -39,6 +39,7 @@
 #include <QScreen>
 #include <QStack>
 #include <QStandardPaths>
+#include <QTextLayout>
 #include <QTimer>
 #include <qplatformdefs.h>

@@ -1023,6 +1024,88 @@ int FolderModel::fileExtensionBoundary(int row)
     return boundary;
 }

+QString FolderModel::elideKeepingExtension(int row, const QString &text, const QFont &font, qreal width, int maxLines)
+{
+    const QString name = data(index(row, 0), Qt::DisplayRole).toString();
+    const int extensionLength = name.length() - fileExtensionBoundary(row);
+
+    if (extensionLength <= 0 || width <= 0 || maxLines < 1) {
+        return text;
+    }
+
+    // Same options as the label, so that lines break and measure the same way
+    QTextOption option;
+    option.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);
+    option.setUseDesignMetrics(true);
+
+    QTextLayout layout(text, font);
+    layout.setTextOption(option);
+    layout.beginLayout();
+    QTextLine lastLine;
+    for (int i = 0; i < maxLines; ++i) {
+        QTextLine line = layout.createLine();
+        if (!line.isValid()) {
+            break;
+        }
+        line.setLineWidth(width);
+        lastLine = line;
+    }
+    layout.endLayout();
+
+    if (!lastLine.isValid() || lastLine.textStart() + lastLine.textLength() >= text.length()) {
+        return text;
+    }
+
+    // The text has invisible break opportunities added, so find where the extension starts in it
+    qsizetype extensionStart = text.length();
+    for (int count = 0; count < extensionLength && extensionStart > 0;) {
+        const QChar c = text.at(--extensionStart);
+        if (c != QChar(0x200b) && c != QChar(0x2060)) {
+            ++count;
+        }
+    }
+
+    if (extensionStart <= lastLine.textStart()) {
+        return text;
+    }
+
+    QTextOption lineOption = option;
+    lineOption.setWrapMode(QTextOption::NoWrap);
+    const auto lineWidth = [&font, &lineOption, width](const QString &line) {
+        QTextLayout lineLayout(line, font);
+        lineLayout.setTextOption(lineOption);
+        lineLayout.beginLayout();
+        QTextLine textLine = lineLayout.createLine();
+        textLine.setLineWidth(width);
+        lineLayout.endLayout();
+        return textLine.naturalTextWidth();
+    };
+
+    const QString ellipsisAndExtension = QStringLiteral("…") + name.right(extensionLength);
+    if (lineWidth(ellipsisAndExtension) > width) {
+        return text;
+    }
+
+    const QString base = text.mid(lastLine.textStart(), extensionStart - lastLine.textStart());
+    qsizetype low = 0;
+    qsizetype high = base.length();
+    while (low < high) {
+        const qsizetype middle = (low + high + 1) / 2;
+        if (lineWidth(base.left(middle) + ellipsisAndExtension) <= width) {
+            low = middle;
+        } else {
+            high = middle - 1;
+        }
+    }
+
+    QString kept = base.left(low);
+    while (!kept.isEmpty() && (kept.back().isSpace() || kept.back() == QChar(0x200b))) {
+        kept.chop(1);
+    }
+
+    return text.left(lastLine.textStart()) + kept + ellipsisAndExtension;
+}
